actions.script:
const out = ec.service.sync().name('ironstone.projects.TimeServices.get#MyWeek').parameters({partyId: partyId || null, weekDate: weekDate || null, appRoot: appRoot || null}).call() || {}
if (ec.message.hasError() || !out.myWeek) { ec.message.clearErrors(); ec.web.sendJsonResponse({notAvailable: true}); return }
ec.web.sendJsonResponse({week: out.myWeek})

const out = ec.service.sync().name('ironstone.projects.TimeServices.save#WeekCell').parameters({partyId: partyId || null, workEffortId: workEffortId || null,
    day: day || '', hours: hours ?? '', billable: billable || null, workTypeEnumId: workTypeEnumId ?? null, comments: comments ?? null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {timeEntryId: out.timeEntryId || null, hours: out.hours})

const out = ec.service.sync().name('ironstone.projects.TimeServices.save#TimeEntry').parameters({timeEntryId: timeEntryId || null, partyId: partyId || null,
    workEffortId: workEffortId || null, day: day || null, fromTime: fromTime || null, thruTime: thruTime || null, hours: hours || null,
    breakHours: breakHours || null, billable: billable || 'Y', workTypeEnumId: workTypeEnumId || null, comments: comments || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {timeEntryId: out.timeEntryId, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.TimeServices.change#WeekRows').parameters({change: change || '', weekDate: weekDate || null,
    workEffortId: workEffortId || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {addedCount: out.addedCount, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.TimeServices.decide#Week').parameters({action: action || '', timesheetId: timesheetId || null,
    weekDate: weekDate || null, reason: reason || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {timesheetId: out.timesheetId, messageInfos: [{type: 'success', message: out.message}]})
